    private static void CreateWorldLabel(string text, Transform parent, Vector3 localOffset, string hexColor)
    {
        GameObject labelObj = new GameObject("Label_" + text);
        labelObj.transform.SetParent(parent, false);
        labelObj.transform.localPosition = localOffset;
        labelObj.transform.localRotation = Quaternion.identity;
        labelObj.transform.localScale = Vector3.one * 0.40f;

        Canvas canvas = labelObj.AddComponent<Canvas>();
        canvas.renderMode = RenderMode.WorldSpace;
        labelObj.AddComponent<CanvasScaler>();
        labelObj.AddComponent<GraphicRaycaster>();

        RectTransform rt = labelObj.GetComponent<RectTransform>();
        rt.sizeDelta = new Vector2(1.00f, 0.20f);

        GameObject textObj = new GameObject("Text");
        textObj.transform.SetParent(labelObj.transform, false);
        RectTransform textRT = textObj.AddComponent<RectTransform>();
        textRT.anchorMin = new Vector2(0.00f, 0.00f);
        textRT.anchorMax = new Vector2(1.00f, 1.00f);
        textRT.offsetMin = Vector2.zero;
        textRT.offsetMax = Vector2.zero;

        Text uiText = textObj.AddComponent<Text>();
        uiText.text = text;
        uiText.alignment = TextAnchor.MiddleCenter;
        uiText.fontSize = 32;
        uiText.font = Resources.GetBuiltinResource<Font>("Arial.ttf");
        Color color;
        if (ColorUtility.TryParseHtmlString(hexColor, out color))
        {
            uiText.color = color;
        }
        else
        {
            uiText.color = Color.white;
        }
    }
}

