public static class GeneratedCode
{
    public static void Execute()
    {
        // 1. Load data
        string dataPath = Path.Combine(Application.streamingAssetsPath, "DxRData/education/student_scores.json");
        if (!File.Exists(dataPath))
        {
            Debug.LogError("Data file not found at: " + dataPath);
            return;
        }

        string jsonData = File.ReadAllText(dataPath);
        JArray data = JArray.Parse(jsonData);

        // 2. Create world-space canvas for the chart
        GameObject chartObj = new GameObject("ScienceScoreChart");
        Canvas canvas = chartObj.AddComponent<Canvas>();
        canvas.renderMode = RenderMode.WorldSpace;
        CanvasScaler scaler = chartObj.AddComponent<CanvasScaler>();
        scaler.dynamicPixelsPerUnit = 10.00f;
        chartObj.AddComponent<GraphicRaycaster>();

        RectTransform rectTransform = chartObj.GetComponent<RectTransform>();
        rectTransform.sizeDelta = new Vector2(1.20f, 0.80f); // width, height in world units

        // 3. Add and configure BarChart
        BarChart chart = chartObj.AddComponent<BarChart>();

        // Title
        var title = chart.GetOrAddChartComponent<Title>();
        title.text = "ScienceScoreChart";
        title.show = true;

        // Legend
        var legend = chart.GetOrAddChartComponent<Legend>();
        legend.show = true;

        // Axes
        var xAxis = chart.GetOrAddChartComponent<XAxis>();
        xAxis.type = Axis.AxisType.Category;
        xAxis.axisLabel.show = true;

        var yAxis = chart.GetOrAddChartComponent<YAxis>();
        yAxis.type = Axis.AxisType.Value;
        yAxis.axisLabel.show = true;

        // 4. Create a green bar series
        Serie serie = chart.AddSerie<Bar>("Science Score");
        // Set bar color to green (#00FF00ff)
        Color32 greenColor = HexToColor32("#00FF00ff");
        serie.itemStyle = new ItemStyle();
        serie.itemStyle.color = greenColor;

        // 5. Populate data
        foreach (var item in data)
        {
            string studentId = item["student_id"].ToString();
            float score = (float)item["science_score"];
            chart.AddXAxisData(studentId);
            chart.AddData(0, score);
        }

        // 6. Position and orient the chart in front of the user
        // User status from prompt:
        // position: (0, 1.7, 0)
        // forward:  (0, 0, -1)
        Vector3 userPosition = new Vector3(0.00f, 1.70f, 0.00f);
        Vector3 userForward = new Vector3(0.00f, 0.00f, -1.00f);

        float distanceInFront = 2.00f;
        Vector3 targetPosition = userPosition + userForward * distanceInFront;

        chartObj.transform.position = targetPosition;

        // Make the chart face the user
        Vector3 lookTarget = userPosition;
        chartObj.transform.rotation = Quaternion.LookRotation(lookTarget - chartObj.transform.position, Vector3.up);

        // 7. Scale chart to a comfortable size
        chartObj.transform.localScale = new Vector3(0.50f, 0.50f, 0.50f);
    }

    private static Color32 HexToColor32(string hex)
    {
        if (string.IsNullOrEmpty(hex) || hex[0] != '#' || hex.Length != 9)
        {
            Debug.LogWarning("Invalid color hex string: " + hex + ", defaulting to white.");
            return new Color32(255, 255, 255, 255);
        }

        byte r = byte.Parse(hex.Substring(1, 2), System.Globalization.NumberStyles.HexNumber);
        byte g = byte.Parse(hex.Substring(3, 2), System.Globalization.NumberStyles.HexNumber);
        byte b = byte.Parse(hex.Substring(5, 2), System.Globalization.NumberStyles.HexNumber);
        byte a = byte.Parse(hex.Substring(7, 2), System.Globalization.NumberStyles.HexNumber);
        return new Color32(r, g, b, a);
    }
}

